class Solution {
public:
    bool checkAdjacentDigitDifferences(string s) {
        vector<int> d;
        for (char c : s) d.push_back(c - '0');
        for (size_t i = 0; i + 1 < d.size(); i++)
            if (abs(d[i] - d[i + 1]) > 2) return false;
        return true;
    }
};

c.java:
class Solution {
    public boolean checkAdjacentDigitDifferences(String s) {
        int[] d = s.chars().map(c -> c - '0').toArray();
        return java.util.stream.IntStream.range(0, d.length - 1)
            .allMatch(i -> Math.abs(d[i] - d[i + 1]) <= 2);
    }
}

